import express from 'express'
// This path will be generated by `backkit add email`
import { createEmailService } from '../backend/email/src/index.js'

const app = express()
app.use(express.json())

// 1. Initialize the Plughub email service
const email = createEmailService({
  host: '127.0.0.1',
  port: 1025,
  user: 'dev',
  password: 'dev',
  secure: false,
})

// 2. Use it in a standard route
app.post('/welcome', async (req, res) => {
  const { email: toAddress } = req.body

  if (!toAddress) {
    return res.status(400).json({ error: 'Email is required' })
  }

  try {
    const result = await email.sendEmail({
      from: { address: 'hello@plughub.dev', name: 'Plughub Team' },
      to: [{ address: toAddress }],
      subject: 'Welcome to the app!',
      text: 'This email was sent via Plughub. No HTTP microservice required.',
    })

    res.json({ success: true, messageId: result.id })
  } catch (error) {
    console.error(error)
    res.status(500).json({ error: 'Failed to send email' })
  }
})

app.listen(3000, () => {
  console.log('Example app running on http://localhost:3000')
})
